#include "../wiegand.h"

static void wiegand_button_callback(GuiButtonType result, InputType type, void* context) {
    App* app = context;
    if(type != InputTypeShort) return;
    if(result == GuiButtonTypeLeft) {
        view_dispatcher_send_custom_event(app->view_dispatcher, WiegandDataSceneSaveButtonEvent);
    } else if(result == GuiButtonTypeRight) {
        view_dispatcher_send_custom_event(app->view_dispatcher, WiegandDataSceneExportRfidEvent);
    }
}

static void wiegand_data_build_text(App* app, FuriString* buffer) {
    int n = bit_count;
    char text[WIEGAND_DECODE_TEXT_SIZE];

    furi_string_printf(buffer, "Bits: %d", n);
    if(!wiegand_format_known_length(n)) {
        furi_string_cat_printf(buffer, " (odd length)");
    }
    if(app->rfid_status[0] != '\0') {
        furi_string_cat_printf(buffer, "\n%s", app->rfid_status);
    }
    if(overflow_bits > 0) {
        furi_string_cat_printf(buffer, "\nTRUNCATED: %lu more bits", overflow_bits);
    }
    if(glitch_count > 0) {
        furi_string_cat_printf(buffer, "\nGlitches: %lu", glitch_count);
    }

    wiegand_format_binary_grouped(data, n, text, sizeof(text));
    furi_string_cat_printf(buffer, "\n%s", text);

    wiegand_format_hex(data, n, false, text, sizeof(text));
    furi_string_cat_printf(buffer, "\nHex: %s", text);
    if(n % 4 != 0) {
        wiegand_format_hex(data, n, true, text, sizeof(text));
        furi_string_cat_printf(buffer, "\nHex left-just: %s", text);
    }

    wiegand_format_decode(data, n, text, sizeof(text));
    if(text[0] != '\0') {
        furi_string_cat_printf(buffer, "\n\n%s", text);
    }

    WiegandTiming timing;
    wiegand_capture_timing(&timing);
    furi_string_cat_printf(buffer, "\n\nTiming us, min/avg/max");
    furi_string_cat_printf(
        buffer, "\nPulse %lu/%lu/%lu", timing.pulse_min, timing.pulse_avg, timing.pulse_max);
    if(timing.has_period) {
        furi_string_cat_printf(
            buffer,
            "\nPeriod %lu/%lu/%lu",
            timing.period_min,
            timing.period_avg,
            timing.period_max);
    }

    furi_string_cat_printf(buffer, "\n\nBit: pulse, period (us)");
    for(int i = 0; i < n; i++) {
        uint32_t pulse = (data_rise[i] - data_fall[i]) / WIEGAND_TICKS_PER_US;
        if(i + 1 < n) {
            uint32_t period = (data_fall[i + 1] - data_fall[i]) / WIEGAND_TICKS_PER_US;
            furi_string_cat_printf(
                buffer, "\n%d %c: %lu, %lu", i + 1, data[i] ? '1' : '0', pulse, period);
        } else {
            furi_string_cat_printf(buffer, "\n%d %c: %lu", i + 1, data[i] ? '1' : '0', pulse);
        }
    }
}

/* Rebuilds the screen from the current capture and status. Does not clear the
 * status, so it can be called again after an export to show the result. */
static void wiegand_data_render(App* app) {
    widget_reset(app->widget);
    widget_add_string_element(app->widget, 0, 0, AlignLeft, AlignTop, FontPrimary, "Wiegand Data");

    bool has_buttons = !data_saved || (wiegand_rfid_keytype(bit_count) != NULL);

    FuriString* buffer = furi_string_alloc();
    wiegand_data_build_text(app, buffer);
    widget_add_text_scroll_element(
        app->widget, 0, 12, 128, has_buttons ? 38 : 52, furi_string_get_cstr(buffer));
    furi_string_free(buffer);

    if(!data_saved) {
        widget_add_button_element(
            app->widget, GuiButtonTypeLeft, "Save", wiegand_button_callback, app);
    }
    if(wiegand_rfid_keytype(bit_count) != NULL) {
        widget_add_button_element(
            app->widget, GuiButtonTypeRight, "To RFID", wiegand_button_callback, app);
    }
    view_dispatcher_switch_to_view(app->view_dispatcher, WiegandWidgetView);
}

void wiegand_data_scene_on_enter(void* context) {
    App* app = context;
    app->rfid_status[0] = '\0'; /* fresh capture, no export yet */
    wiegand_data_render(app);
}

bool wiegand_data_scene_on_event(void* context, SceneManagerEvent event) {
    App* app = context;
    bool consumed = false;
    if(event.type == SceneManagerEventTypeCustom) {
        if(event.event == WiegandDataSceneSaveButtonEvent) {
            scene_manager_next_scene(app->scene_manager, WiegandSaveScene);
            consumed = true;
        } else if(event.event == WiegandDataSceneExportRfidEvent) {
            wiegand_export_rfid(app);
            wiegand_data_render(app);
            consumed = true;
        }
    }
    return consumed;
}
